{
  "kind": "multi-payment",
  "key": "variable-on-demand",
  "label": "Variable On-Demand",
  "apiName": "Bank Service Initiation",
  "paymentType": "VariableOnDemand",
  "role": "lfi",
  "certType": "LFI Functional Certification Evidence",
  "tppBaseUrlTemplate": "https://rs1.{LFICODE}.apihub.openfinance.ae/open-finance/payment/{VERSION}",
  "segments": [
    "Retail",
    "SME",
    "Corporate"
  ],
  "requiredControls": [
    "PeriodType",
    "PeriodStartDate",
    "Controls (≥ 1 of the below)"
  ],
  "optionalControls": [
    "MaximumCumulativeValueOfPayments",
    "MaximumCumulativeNumberOfPayments",
    "Controls.MaximumIndividualAmount",
    "Controls.MaximumCumulativeValueOfPaymentsPerPeriod",
    "Controls.MaximumCumulativeNumberOfPaymentsPerPeriod"
  ],
  "docHref": "/tech/lfi-api-hub/v2.1/banking/service-initiation/domestic-payments/multi-payments/variable-on-demand/api-guide",
  "sandboxEvidenceHref": "/tech/lfi-api-hub/getting-started/",
  "scenarios": [
    {
      "key": "all-set",
      "label": "All control parameters set",
      "guidance": "Create a Variable On-Demand consent with every optional control parameter populated — the consent-level cumulative caps (MaximumCumulativeValueOfPayments, MaximumCumulativeNumberOfPayments) and the per-period controls (Controls.MaximumIndividualAmount, Controls.MaximumCumulativeValueOfPaymentsPerPeriod, Controls.MaximumCumulativeNumberOfPaymentsPerPeriod). Your authorization screen must surface these limits to the customer.",
      "example": "{
    "IsDelegatedAuthentication": false,
    "ConsentSchedule": {
      "MultiPayment": {
        "MaximumCumulativeValueOfPayments": { "Amount": "10000.00", "Currency": "AED" },
        "MaximumCumulativeNumberOfPayments": 24,
        "PeriodicSchedule": {
          "Type": "VariableOnDemand",
          "PeriodType": "Month",
          "PeriodStartDate": "2026-08-01",
          "Controls": {
            "MaximumIndividualAmount": { "Amount": "1000.00", "Currency": "AED" },
            "MaximumCumulativeValueOfPaymentsPerPeriod": { "Amount": "3000.00", "Currency": "AED" },
            "MaximumCumulativeNumberOfPaymentsPerPeriod": 5
          }
        }
      }
    }
  }"
    },
    {
      "key": "optional-not-set",
      "label": "Optional control parameters not set",
      "guidance": "Create a second Variable On-Demand consent carrying only the required minimum (PeriodType, PeriodStartDate, Controls (≥ 1 of the below)) — omit the optional caps (MaximumCumulativeValueOfPayments, MaximumCumulativeNumberOfPayments) and every optional per-period control beyond the required minimum. This proves your LFI handles a consent with no optional ceilings.",
      "example": "{
    "IsDelegatedAuthentication": false,
    "ConsentSchedule": {
      "MultiPayment": {
        "PeriodicSchedule": {
          "Type": "VariableOnDemand",
          "PeriodType": "Month",
          "PeriodStartDate": "2026-08-01",
          "Controls": {
            "MaximumIndividualAmount": { "Amount": "1000.00", "Currency": "AED" }
          }
        }
      }
    }
  }"
    }
  ],
  "beneficiaryModels": [
    {
      "key": "multiple",
      "label": "Multiple Beneficiaries",
      "description": "The consent fixes 2–10 creditor entries in Initiation.Creditor. Every subsequent payment’s creditor must exactly match one of them.",
      "trustFrameworkFlag": "ApiMetadata.VariableOnDemand.MultipleBeneficiariesSupported",
      "referencePii": "{
  "Initiation": {
    "DebtorAccount": {
      "SchemeName": "IBAN",
      "Identification": "AE460090000000123456789"
    },
    "Creditor": [
      {
        "Creditor": {
          "Name": "Ivan England"
        },
        "CreditorAccount": {
          "SchemeName": "IBAN",
          "Identification": "AE070331234567890123456",
          "Name": {
            "en": "Ivan David England"
          }
        }
      },
      {
        "Creditor": {
          "Name": "Al Noor Trading LLC"
        },
        "CreditorAccount": {
          "SchemeName": "IBAN",
          "Identification": "AE320260001234567890123",
          "Name": {
            "en": "Al Noor Trading LLC"
          }
        }
      },
      {
        "Creditor": {
          "Name": "Emirates Telecommunications Group"
        },
        "CreditorAccount": {
          "SchemeName": "IBAN",
          "Identification": "AE980350000009876543210",
          "Name": {
            "en": "Emirates Telecommunications Group"
          }
        }
      }
    ]
  }
}",
      "collectsCreditorArray": true
    },
    {
      "key": "open",
      "label": "Open Beneficiaries",
      "description": "The consent omits Initiation.Creditor entirely. No creditor is fixed at consent; the TPP supplies it on each POST /payments, where your Ozone Connect endpoint validates it.",
      "trustFrameworkFlag": "ApiMetadata.VariableOnDemand.OpenBeneficiariesSupported",
      "referencePii": "{
  "Initiation": {
    "DebtorAccount": {
      "SchemeName": "IBAN",
      "Identification": "AE460090000000123456789"
    }
  }
}",
      "collectsCreditorArray": false
    }
  ],
  "creditorDocHref": "/tech/lfi-api-hub/v2.1/banking/service-initiation/personal-identifiable-information/creditor"
}
